//! USB mass storage (SCSI over Bulk-Only Transport, usbd-storage), always
//! present in the composite device.
//!
//! The media are `BlockDevice`s, one per LUN (`Msc::new(.., luns)`, GET MAX
//! LUN = luns - 1; every command goes to the device of its CBW's LUN):
//!   `vdisk` (default): ONE LUN, the volume generated by vdisk.rs (LOGS /
//!     SCOPE / SHOTS / INFO / DEBUG), writable only for what vwrite.rs
//!     accepts (deletes, a firmware file; `gates_writes`: it answers every
//!     block itself); the SPI flash is internal storage only (fatdir.rs);
//!   without `vdisk`, and recovery-usb: the on-board
//!     W25Q128 (spiflash.rs), the stock FAT16 volume with 4096-byte sectors
//!     (stock/re/analysis/spiflash_v2_6.h), writable.
//! INQUIRY gives each device's product name (removable); with EVPD, page
//! 0x00 (supported pages: 00, 80) and 0x80 (unit serial number = the chip
//! UID, src/uid.rs, as the USB iSerial), any other page fails 05/24/00
//! (Linux usb-storage never asks: skip_vpd_pages; Windows / macOS do). READ CAPACITY /
//! READ FORMAT CAPACITIES its geometry, MODE SENSE the write-protect bit of
//! a read-only device, and a WRITE to it fails with DATA PROTECT, WRITE
//! PROTECTED (07/27/00) without touching anything. Sense data is per LUN.
//! The host lock (PREVENT ALLOW MEDIUM REMOVAL) is tracked per LUN;
//! `host_mounted` = LUN 0's. The one-shot UNIT ATTENTION 06/28/00 after a
//! change: a device with `media_change_immediate` (vdisk.rs) gets it at
//! once, also while locked (the 2026-10-21 experiment: Linux re-reads the
//! mounted volume); the writable SPI disk's (screenshot::MEDIUM_CHANGED) is
//! held back while locked, as before.
//! Eject (START STOP UNIT with LoEj = 1, Start = 0: Linux `eject` / a file
//! manager's Eject, Windows "Eject" / Safely remove): the LUN has no medium
//! (every command but INQUIRY / REQUEST SENSE / START STOP / PREVENT fails
//! 02/3A/00, READ FORMAT CAPACITIES included) until a bus reset (a re-plug,
//! or the host re-enumerating) or a host load (LoEj = 1, Start = 1), which
//! then raises the one-shot UNIT ATTENTION 06/28/00. Without it a host that
//! polls the removable disk (Windows) mounts it again at once. A plain
//! STOP / START (LoEj = 0: Linux sd around a suspend, udisks' power-off)
//! changes nothing. Media-change UNIT ATTENTIONs are not consumed while
//! ejected: they go out after the load / re-plug.

use usb_device::class_prelude::*;
use usb_device::prelude::UsbDeviceState;
use usbd_storage::subclass::scsi::{Scsi, ScsiCommand};
use usbd_storage::subclass::Command;
use usbd_storage::transport::bbb::{BulkOnly, BulkOnlyError};
use usbd_storage::transport::TransportError;

/// Largest block of the devices served: 512 (the generated volume) in the
/// native build, 4096 (the SPI disk) where that is exported.
pub const MAX_BLOCK: usize = if cfg!(all(feature = "vdisk", not(feature = "recovery-usb"))) { 512 } else { 4096 };

/// Block storage behind the USB disk.
pub trait BlockDevice {
    /// Medium available (false = "no medium").
    fn present(&self) -> bool;
    fn block_size(&self) -> u32;
    fn block_count(&self) -> u32;
    fn read_block(&mut self, lba: u32, buf: &mut [u8]) -> bool;
    fn write_block(&mut self, lba: u32, buf: &[u8]) -> bool;
    /// Write-protected medium (MODE SENSE WP bit; WRITE fails with DATA
    /// PROTECT before any data is taken).
    fn read_only(&self) -> bool {
        false
    }
    /// One-shot "the volume changed under the host" (vdisk.rs `refresh`):
    /// true once, and the next command of this LUN gets UNIT ATTENTION
    /// 06/28/00. The writable SPI disk uses screenshot::MEDIUM_CHANGED.
    fn take_media_changed(&mut self) -> bool {
        false
    }
    /// The UNIT ATTENTION goes out at once, also while the host holds the
    /// medium locked (a generated read-only volume: nothing of the host's
    /// can go stale in a harmful way, it only has to re-read).
    fn media_change_immediate(&self) -> bool {
        false
    }
    /// INQUIRY product identification (16 characters).
    fn product(&self) -> &'static [u8; 16] {
        b"DM40 disk       "
    }
    /// The device decides about every written block itself (vdisk.rs /
    /// vwrite.rs: most host writes only change its model; it answers "busy"
    /// for the ones that need the SPI flash while an on-device writer holds
    /// it), so the global write inhibits (screenshot, CSV session, logger)
    /// do not apply.
    fn gates_writes(&self) -> bool {
        false
    }
    /// Why the last `write_block` failed: 0 a medium error (03/0C/00), 1
    /// refused (DATA PROTECT, WRITE PROTECTED 07/27/00), 2 busy, retry
    /// (NOT READY, BECOMING READY 02/04/01).
    fn write_error(&self) -> u8 {
        0
    }
    /// Blocks `lba .. lba + n` cannot be read now, but can later: the READ
    /// fails with NOT READY, BECOMING READY (02/04/01) before its data phase
    /// (or at the first such block of a transfer in progress) and the host
    /// retries it (vdisk.rs: the sectors served from the slow flash bank
    /// while the AD2 stream ISR runs).
    fn read_busy(&self, lba: u32, n: u32) -> bool {
        let _ = (lba, n);
        false
    }
    /// Block `lba` (the next of a READ in progress) is better read in a
    /// later main-loop pass: the transfer waits in its data phase (nothing
    /// sent, the host's IN tokens are NAKed) and the block is asked for
    /// again at the next poll. Must turn false within a bounded time
    /// (vdisk.rs: a mirror sector paced against the fast logger, at most
    /// 50 ms per sector).
    fn read_wait(&mut self, lba: u32) -> bool {
        let _ = lba;
        false
    }
    /// `write_block` spread over several calls, for a caller that must not
    /// stall the main loop (screenshot.rs, csvlog.rs). Call again with the
    /// same `lba`, `buf` and `st` (starting from `Step::default()`) until it
    /// returns Some(ok). `buf` is a byte slice or a word-only RAM (wordram.rs
    /// `BlockSrc`). Default: the whole write at once, from a byte slice only.
    fn write_step(&mut self, lba: u32, buf: &dyn crate::wordram::BlockSrc, st: &mut Step) -> Option<bool> {
        let _ = st;
        match buf.bytes() {
            Some(b) => Some(self.write_block(lba, b)),
            None => Some(false),
        }
    }
}

/// Progress of one `BlockDevice::write_step` block write (spiflash.rs).
#[derive(Clone, Copy, Default)]
pub struct Step {
    pub started: bool,
    /// 0 compare, 1 erase, 2 program, 3 read back.
    pub phase: u8,
    pub page: u8,
    /// Pages to program (bit = page).
    pub dirty: u16,
    pub erase: bool,
    /// Start of the current wait (DWT cycles), for the timeout.
    pub t0: u32,
}

/// A host WRITE(10) is in progress (between its first and last block), so an
/// on-device writer (screenshot.rs) waits before reading the FAT.
pub static HOST_WRITING: core::sync::atomic::AtomicBool = core::sync::atomic::AtomicBool::new(false);
/// A host READ or WRITE command started since main.rs last looked (it
/// takes it: the host's disk use counts as activity for the idle shutdown,
/// App::note_host_activity). TEST UNIT READY and the other polls do not set
/// it: a host that only polls the medium does not keep the meter on.
pub static HOST_IO: core::sync::atomic::AtomicBool = core::sync::atomic::AtomicBool::new(false);
/// Bumped by every program / erase command sent to the SPI flash
/// (spiflash.rs `write_enable`): screenshot.rs `prep_poll` sees from it that
/// another writer changed the disk since its last step and starts over.
pub static FLASH_WRITES: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);

/// A CSV recording session is active (csvlog.rs): host writes are refused
/// for the whole session (its cached FAT / directory state must not go stale).
/// Set and cleared by csvlog only.
pub static LOG_SESSION: core::sync::atomic::AtomicBool = core::sync::atomic::AtomicBool::new(false);
/// A csvlog commit is writing the disk: screenshot.rs waits before its FAT
/// scan (one on-device writer at a time). Set and cleared by csvlog only.
pub static LOG_FLUSHING: core::sync::atomic::AtomicBool = core::sync::atomic::AtomicBool::new(false);

#[derive(Clone, Copy, PartialEq, Eq)]
enum Xfer {
    None,
    Read { lba: u32, left: u32, off: usize, done: u32 },
    Write { lba: u32, left: u32, off: usize, done: u32 },
    /// A refused WRITE: its data phase is read and dropped, then the
    /// command fails (sense already set). `left` bytes still to take.
    Discard { left: u32 },
}

/// Sense key / ASC / ASCQ for REQUEST SENSE.
#[derive(Clone, Copy)]
struct Sense(u8, u8, u8);

const SENSE_OK: Sense = Sense(0, 0, 0);
const SENSE_NO_MEDIUM: Sense = Sense(0x02, 0x3A, 0x00);
const SENSE_INVALID: Sense = Sense(0x05, 0x20, 0x00);
const SENSE_LBA_RANGE: Sense = Sense(0x05, 0x21, 0x00);
const SENSE_MEDIUM_ERROR: Sense = Sense(0x03, 0x11, 0x00);
/// MEDIUM ERROR, WRITE ERROR (a failed block write).
const SENSE_WRITE_ERROR: Sense = Sense(0x03, 0x0C, 0x00);
/// NOT READY, LOGICAL UNIT IS IN PROCESS OF BECOMING READY (writes
/// inhibited; READs of `BlockDevice::read_busy` blocks). ASCQ 01, not 00
/// ("cause not reportable"): Linux (scsi_io_completion_action) delays and
/// retries 04/01 but fails 04/00 at once, i.e. a host write during a
/// screenshot would get EIO (review 60605d2 M1).
const SENSE_BECOMING_READY: Sense = Sense(0x02, 0x04, 0x01);
/// UNIT ATTENTION, NOT READY TO READY CHANGE, MEDIUM MAY HAVE CHANGED: the
/// firmware itself wrote the disk (screenshot.rs), the host must re-read it.
const SENSE_MEDIUM_CHANGED: Sense = Sense(0x06, 0x28, 0x00);
/// DATA PROTECT, WRITE PROTECTED: a WRITE to a read-only LUN.
const SENSE_WRITE_PROTECTED: Sense = Sense(0x07, 0x27, 0x00);
/// ILLEGAL REQUEST, INVALID FIELD IN CDB (an INQUIRY VPD page we lack).
const SENSE_INVALID_FIELD: Sense = Sense(0x05, 0x24, 0x00);
/// ILLEGAL REQUEST, LOGICAL UNIT NOT SUPPORTED (a LUN above GET MAX LUN).
const SENSE_BAD_LUN: Sense = Sense(0x05, 0x25, 0x00);

/// LUNs at most.
pub const MAX_LUNS: usize = 2;

/// A host has the medium of LUN i locked: its last PREVENT ALLOW MEDIUM
/// REMOVAL (0x1E) had Prevent = 1. Linux sends it on the first open of the
/// block device (mount) and Allow on the last close (umount / eject).
/// Cleared by an Allow, a bus reset (`Msc::reset`) and an unconfigure
/// (`set_usb_state`: Default / Addressed), NOT by a USB suspend: Linux
/// runtime autosuspend of an idle mounted disk keeps the mount (and sends no
/// PREVENT again on resume), review 6595d46 M2. VBUS sensing is off (usb.rs),
/// so an unplug without eject also looks like a suspend: the lock then stays
/// set until the replug's bus reset or a reboot, the safe side. What it
/// gates: the writable SPI disk's UNIT ATTENTION (held back), the generated
/// volume's compaction (vdisk.rs: only while unlocked).
static LOCKED: [core::sync::atomic::AtomicBool; MAX_LUNS] = [const { core::sync::atomic::AtomicBool::new(false) }; MAX_LUNS];

fn unlock_all() {
    for l in &LOCKED {
        l.store(false, core::sync::atomic::Ordering::Relaxed);
    }
}

/// DBG:VDISK:EJECT n: the next n commands (not INQUIRY / REQUEST SENSE) to
/// the generated volume fail with NOT READY, MEDIUM NOT PRESENT, then a
/// UNIT ATTENTION.
pub static DBG_EJECT: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);
static EJECT_UA: core::sync::atomic::AtomicBool = core::sync::atomic::AtomicBool::new(false);

/// LUN i was ejected by the host (START STOP UNIT, LoEj = 1, Start = 0):
/// "no medium" until a bus reset / unconfigure or a host load (module text).
static EJECTED: [core::sync::atomic::AtomicBool; MAX_LUNS] = [const { core::sync::atomic::AtomicBool::new(false) }; MAX_LUNS];
/// LUN i was loaded again by the host (LoEj = 1, Start = 1): its next
/// command gets the UNIT ATTENTION 06/28/00.
static LOADED_UA: [core::sync::atomic::AtomicBool; MAX_LUNS] = [const { core::sync::atomic::AtomicBool::new(false) }; MAX_LUNS];
/// START STOP UNIT commands seen since boot, and CB[4] of the last one
/// (0x100 = its CBW could not be told apart from host data: ignored), for
/// DBG:VDISK:EJECT?.
pub static SSU_COUNT: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);
pub static SSU_LAST: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);

/// A bus reset / unconfigure: every LUN has its medium again (a re-plug).
fn reload_all() {
    for (e, u) in EJECTED.iter().zip(&LOADED_UA) {
        e.store(false, core::sync::atomic::Ordering::Relaxed);
        u.store(false, core::sync::atomic::Ordering::Relaxed);
    }
}

/// LUN `lun` ejected by the host (DBG:VDISK:EJECT?).
pub fn ejected(lun: usize) -> bool {
    EJECTED.get(lun).is_some_and(|e| e.load(core::sync::atomic::Ordering::Relaxed))
}

/// A host has LUN 0 locked (mounted on Linux; see LOCKED).
pub fn host_mounted() -> bool {
    LOCKED[0].load(core::sync::atomic::Ordering::Relaxed)
}

/// The I/O buffer handed to usbd-storage, shared through a raw pointer so
/// that `handle` can read the CDB bytes the crate does not expose (the
/// Prevent bit of 0x1E; usbd-storage 3.0.0 only reports the opcode). Neither
/// side keeps a slice borrowed across calls.
pub struct IoBuf {
    p: *mut u8,
    n: usize,
}

impl core::borrow::Borrow<[u8]> for IoBuf {
    fn borrow(&self) -> &[u8] {
        unsafe { core::slice::from_raw_parts(self.p, self.n) }
    }
}

impl core::borrow::BorrowMut<[u8]> for IoBuf {
    fn borrow_mut(&mut self) -> &mut [u8] {
        unsafe { core::slice::from_raw_parts_mut(self.p, self.n) }
    }
}

/// CB[4] of the no-data command `op` being handled (PREVENT ALLOW MEDIUM
/// REMOVAL 0x1E: bit 0 = Prevent; START STOP UNIT 0x1B: bit 0 = Start, bit 1
/// = LoEj), read from its CBW in the transport buffer. When the callback
/// runs, the 31-byte CBW the crate has just parsed is still in `io` (it is
/// read in place, the buffer is only written again for the data / status
/// phase): "USBC", tag, data length 0, flags, LUN `lun`, CB length, CB[0] =
/// `op`. Every match is then defaced (signature zeroed), so a stale CBW of
/// an earlier one can never be found again; None when not exactly one match
/// is left (host data that happens to look like one).
fn cdb4(io: &mut [u8], lun: u8, op: u8) -> Option<u8> {
    let (mut found, mut b4) = (0u32, 0u8);
    let mut o = 0usize;
    while o + 31 <= io.len() {
        let c = &io[o..o + 31];
        if c[..4] == *b"USBC" && c[8..12] == [0; 4] && c[13] == lun && (6..=16).contains(&c[14]) && c[15] == op {
            found += 1;
            b4 = c[19];
            io[o..o + 4].fill(0);
            o += 31;
        } else {
            o += 1;
        }
    }
    (found == 1).then_some(b4)
}

pub struct Msc<'a, B: UsbBus> {
    pub scsi: Scsi<BulkOnly<'a, B, IoBuf>>,
    io: IoBuf,
    xfer: Xfer,
    /// Per LUN.
    sense: [Sense; MAX_LUNS],
    /// Block buffer (a static from main.rs, in SRAM: not on the main stack).
    blk: &'static mut [u8; MAX_BLOCK],
    /// Refuse host writes (NOT READY, becoming ready) while set (M4: the
    /// logger's constant sample interval cannot survive a 50..400 ms erase).
    write_inhibit: bool,
    /// This poll's READ block waits (`BlockDevice::read_wait`).
    waiting: bool,
}

type Res = Result<(), TransportError<BulkOnlyError>>;

impl<'a, B: UsbBus> Msc<'a, B> {
    /// `luns`: 1 (SPI disk) or 2 (+ the information volume); GET MAX LUN
    /// answers `luns - 1`, `poll` takes that many devices.
    pub fn new(alloc: &'a UsbBusAllocator<B>, io: &'static mut [u8], blk: &'static mut [u8; MAX_BLOCK], luns: u8) -> Self {
        let (p, n) = (io.as_mut_ptr(), io.len());
        let max_lun = luns.clamp(1, MAX_LUNS as u8) - 1;
        let scsi = Scsi::new(alloc, 64, max_lun, IoBuf { p, n }).unwrap_or_else(|_| panic!("msc"));
        Msc { scsi, io: IoBuf { p, n }, xfer: Xfer::None, sense: [SENSE_OK; MAX_LUNS], blk, write_inhibit: false, waiting: false }
    }

    /// The USB device state (main loop, every pass). Default / Addressed
    /// (bus reset, SET_CONFIGURATION 0): no host can have the disk mounted,
    /// the lock is cleared. Suspend keeps it (see LOCKED).
    pub fn set_usb_state(&mut self, st: UsbDeviceState) {
        if matches!(st, UsbDeviceState::Default | UsbDeviceState::Addressed) {
            unlock_all();
            reload_all();
        }
    }

    /// Serve pending SCSI commands from the main loop. `devs[i]` = LUN i.
    pub fn poll(&mut self, devs: &mut [&mut dyn BlockDevice]) {
        let xfer = &mut self.xfer;
        let sense = &mut self.sense;
        let blk = &mut *self.blk;
        let io = &mut self.io;
        self.waiting = false;
        let waiting = &mut self.waiting;
        // Also no host writes while a screenshot is being written (its FAT /
        // directory update spans many main-loop passes) or a CSV recording
        // session is active (csvlog.rs).
        let inhibit = self.write_inhibit
            || crate::screenshot::busy()
            || LOG_SESSION.load(core::sync::atomic::Ordering::Relaxed);
        let _ = self.scsi.poll_command(|cmd| -> Res {
            let lun = cmd.lun as usize;
            match (devs.get_mut(lun), sense.get_mut(lun)) {
                (Some(dev), Some(sense)) => handle(cmd, &mut **dev, xfer, sense, blk, io, inhibit, waiting),
                _ => bad_lun(cmd),
            }
        });
        HOST_WRITING.store(matches!(self.xfer, Xfer::Write { .. }), core::sync::atomic::Ordering::Relaxed);
    }

    /// A host READ's data phase is under way (and its next block does not
    /// wait for a later pass, `read_wait`): main.rs polls again within the
    /// pass (usbd-storage moves one 64-byte packet per poll, ~2 per main-loop
    /// pass otherwise: ~0.1 MB/s at a 1 ms pass).
    pub fn reading(&self) -> bool {
        (matches!(self.xfer, Xfer::Read { .. }) && !self.waiting) || self.scsi.sending()
    }

    /// Block (true) or allow host writes; a write already in progress finishes.
    pub fn set_write_inhibit(&mut self, on: bool) {
        self.write_inhibit = on;
    }
}

type Cmd<'c, 'a, B> = Command<'c, ScsiCommand, Scsi<BulkOnly<'a, B, IoBuf>>>;

/// A short reply (INQUIRY, REQUEST SENSE, MODE SENSE, READ CAPACITY, READ
/// FORMAT CAPACITIES), passed with the count sent: at most what the host
/// asked for (`write_data` stops at the CBW's length; the whole reply went
/// out before, more than a short allocation length), nothing with no data
/// phase (a 0 length: `write_data` fails there, and the command used to
/// stay without status: no CSW ever).
fn reply<B: UsbBus>(mut cmd: Cmd<'_, '_, B>, d: &[u8]) {
    let n = cmd.write_data(d).unwrap_or(0);
    cmd.pass(n as u32);
}

/// A LUN above GET MAX LUN (a host should never address one): INQUIRY says
/// "no device here" (peripheral qualifier 3), REQUEST SENSE "LUN not
/// supported", anything else fails.
fn bad_lun<B: UsbBus>(cmd: Cmd<'_, '_, B>) -> Res {
    match cmd.kind {
        ScsiCommand::Inquiry { .. } => {
            let mut d = [0u8; 36];
            d[0] = 0x7F;
            d[4] = 31;
            reply(cmd, &d);
        }
        ScsiCommand::RequestSense { .. } => {
            let s = SENSE_BAD_LUN;
            let d = [0x70, 0, s.0, 0, 0, 0, 0, 10, 0, 0, 0, 0, s.1, s.2, 0, 0, 0, 0];
            reply(cmd, &d);
        }
        _ => cmd.fail(0),
    }
    Ok(())
}

fn handle<B: UsbBus>(
    mut cmd: Cmd<'_, '_, B>,
    dev: &mut dyn BlockDevice,
    xfer: &mut Xfer,
    sense: &mut Sense,
    blk: &mut [u8; MAX_BLOCK],
    io: &mut IoBuf,
    write_inhibit: bool,
    waiting: &mut bool,
) -> Res {
    let kind = cmd.kind;
    let lun = cmd.lun;
    let bs = dev.block_size();
    let o = core::sync::atomic::Ordering::Relaxed;
    let first = *xfer == Xfer::None && !matches!(kind, ScsiCommand::Inquiry { .. } | ScsiCommand::RequestSense { .. });
    // Ejected by the host: no medium, for everything but the commands that
    // load it again or lock / unlock it (and INQUIRY / REQUEST SENSE).
    // Before the UNIT ATTENTIONs: those wait for the load / re-plug.
    if first && ejected(lun as usize) && !matches!(kind, ScsiCommand::Unknown { cmd: 0x1B | 0x1E }) {
        *sense = SENSE_NO_MEDIUM;
        cmd.fail(0);
        return Ok(());
    }
    // DBG:VDISK:EJECT: "no medium" for n commands, then a UNIT ATTENTION.
    if first && dev.media_change_immediate() && DBG_EJECT.load(o) > 0 {
        if DBG_EJECT.fetch_sub(1, o) == 1 {
            EJECT_UA.store(true, o);
        }
        *sense = SENSE_NO_MEDIUM;
        cmd.fail(0);
        return Ok(());
    }
    // One-shot UNIT ATTENTION after a change of the medium: the next command
    // fails with 06/28/00, so the host drops its cached FAT / directories
    // and re-reads the volume. Only at the start of a command (a multi-block
    // transfer in progress is never cut), never for INQUIRY / REQUEST SENSE
    // (SPC: they do not report it). The generated volume's goes out at once,
    // also while locked; the writable SPI disk's (screenshot.rs sets
    // MEDIUM_CHANGED) is held back while a host has it locked (mounted Linux
    // vfat: its writes from a stale FAT would be worse, review 60605d2 M2)
    // and goes out after the Allow (umount).
    if first {
        // After a host load (one UNIT ATTENTION, whatever else is pending).
        let loaded = LOADED_UA.get(lun as usize).is_some_and(|u| u.swap(false, o));
        let ua = loaded | if dev.media_change_immediate() {
            dev.take_media_changed() | EJECT_UA.swap(false, o)
        } else if !LOCKED.get(lun as usize).is_some_and(|l| l.load(o)) {
            if dev.read_only() { dev.take_media_changed() } else { crate::screenshot::MEDIUM_CHANGED.swap(false, o) }
        } else {
            false
        };
        if ua {
            *sense = SENSE_MEDIUM_CHANGED;
            cmd.fail(0);
            return Ok(());
        }
    }
    match kind {
        ScsiCommand::Inquiry { evpd: true, page_code, .. } => {
            // VPD: header (device type 0, page, length) + the page.
            let mut d = [0u8; 4 + 24];
            d[1] = page_code;
            let n = match page_code {
                0x00 => {
                    d[4] = 0x00;
                    d[5] = 0x80;
                    2
                }
                0x80 => {
                    d[4..].copy_from_slice(crate::uid::bytes());
                    24
                }
                _ => {
                    *sense = SENSE_INVALID_FIELD;
                    cmd.fail(0);
                    return Ok(());
                }
            };
            d[3] = n as u8;
            reply(cmd, &d[..4 + n]);
        }
        ScsiCommand::Inquiry { .. } => {
            let mut d = [0u8; 36];
            d[0] = 0x00; // direct access block device
            d[1] = 0x80; // removable
            d[2] = 0x04; // SPC-2
            d[3] = 0x02;
            d[4] = 31;
            d[8..16].copy_from_slice(b"ALIENTEK");
            d[16..32].copy_from_slice(dev.product());
            d[32..36].copy_from_slice(b"0.2 ");
            reply(cmd, &d);
        }
        ScsiCommand::TestUnitReady => {
            if dev.present() {
                *sense = SENSE_OK;
                cmd.pass(0);
            } else {
                *sense = SENSE_NO_MEDIUM;
                cmd.fail(0);
            }
        }
        ScsiCommand::RequestSense { .. } => {
            let s = *sense;
            let d = [0x70, 0, s.0, 0, 0, 0, 0, 10, 0, 0, 0, 0, s.1, s.2, 0, 0, 0, 0];
            *sense = SENSE_OK;
            reply(cmd, &d);
        }
        ScsiCommand::ModeSense6 { .. } => {
            // Mode parameter header only (no block descriptors, no pages);
            // device-specific parameter bit 7 = write protected.
            let wp = if dev.read_only() { 0x80 } else { 0 };
            let d = [3u8, 0, wp, 0];
            reply(cmd, &d);
        }
        ScsiCommand::ModeSense10 { .. } => {
            let wp = if dev.read_only() { 0x80 } else { 0 };
            let d = [0u8, 6, 0, wp, 0, 0, 0, 0];
            reply(cmd, &d);
        }
        ScsiCommand::ReadCapacity10 => {
            if !dev.present() {
                *sense = SENSE_NO_MEDIUM;
                cmd.fail(0);
            } else {
                let mut d = [0u8; 8];
                d[..4].copy_from_slice(&(dev.block_count() - 1).to_be_bytes());
                d[4..].copy_from_slice(&bs.to_be_bytes());
                reply(cmd, &d);
            }
        }
        ScsiCommand::ReadFormatCapacities { .. } => {
            let mut d = [0u8; 12];
            d[3] = 8;
            let (n, kind) = if dev.present() { (dev.block_count(), 2u8) } else { (0xFFFF_FFFF, 3u8) };
            d[4..8].copy_from_slice(&n.to_be_bytes());
            d[8] = kind; // 2 formatted media, 3 no media
            d[9..12].copy_from_slice(&bs.to_be_bytes()[1..]);
            reply(cmd, &d);
        }
        ScsiCommand::Read { lba, len } => {
            if !dev.present() {
                *sense = SENSE_NO_MEDIUM;
                cmd.fail(0);
                return Ok(());
            }
            if *xfer == Xfer::None {
                if lba + len as u32 > dev.block_count() {
                    *sense = SENSE_LBA_RANGE;
                    cmd.fail(0);
                    return Ok(());
                }
                if dev.read_busy(lba, len as u32) {
                    *sense = SENSE_BECOMING_READY;
                    cmd.fail(0);
                    return Ok(());
                }
                *xfer = Xfer::Read { lba, left: len as u32, off: 0, done: 0 };
                HOST_IO.store(true, core::sync::atomic::Ordering::Relaxed);
            }
            if let Xfer::Read { lba, left, off, done } = *xfer {
                let mut off = off;
                // Became busy during the transfer (a stream started): the
                // command fails here, the host retries all of it.
                if off == 0 && dev.read_busy(lba, 1) {
                    *xfer = Xfer::None;
                    *sense = SENSE_BECOMING_READY;
                    cmd.fail(done);
                    return Ok(());
                }
                if off == 0 && dev.read_wait(lba) {
                    // Paced (`read_wait`): no data this poll; the pass's
                    // pump loop stops polling for it (`reading`).
                    *waiting = true;
                    return Ok(());
                }
                if off == 0 && !dev.read_block(lba, &mut blk[..bs as usize]) {
                    *xfer = Xfer::None;
                    // Busy now (vdisk.rs: its slow-bank mirror failed a
                    // read and is off): NOT READY, the host retries.
                    *sense = if dev.read_busy(lba, 1) { SENSE_BECOMING_READY } else { SENSE_MEDIUM_ERROR };
                    cmd.fail(done);
                    return Ok(());
                }
                // Err: the host's data phase is over (its length is shorter
                // than the READ's, or 0): a phase error (BOT 6.7.2), never
                // a command left without status (the host would wait for
                // its CSW until its timeout).
                let Ok(n) = cmd.write_data(&blk[off..bs as usize]) else {
                    *xfer = Xfer::None;
                    cmd.fail_phase();
                    return Ok(());
                };
                off += n;
                let done = done + n as u32;
                if off >= bs as usize {
                    if left <= 1 {
                        *xfer = Xfer::None;
                        cmd.pass(done);
                        return Ok(());
                    }
                    *xfer = Xfer::Read { lba: lba + 1, left: left - 1, off: 0, done };
                } else {
                    *xfer = Xfer::Read { lba, left, off, done };
                }
            }
        }
        ScsiCommand::Write { lba, len } => {
            // A refused WRITE still takes its whole data phase (dropped) and
            // only then fails: failing at once leaves the data to
            // usbd-storage's "read up to the residue" path, which never sent
            // the CSW in the emulator (USB/IP, 2026-10-21: the host waited
            // forever for it). The host's data length is len x block size.
            if *xfer == Xfer::None {
                let refuse = if !dev.present() {
                    Some(SENSE_NO_MEDIUM)
                } else if dev.read_only() {
                    Some(SENSE_WRITE_PROTECTED)
                } else if write_inhibit && !dev.gates_writes() {
                    Some(SENSE_BECOMING_READY)
                } else if lba + len as u32 > dev.block_count() {
                    Some(SENSE_LBA_RANGE)
                } else {
                    None
                };
                HOST_IO.store(true, core::sync::atomic::Ordering::Relaxed);
                *xfer = match refuse {
                    Some(s) => {
                        *sense = s;
                        Xfer::Discard { left: len as u32 * bs }
                    }
                    None => Xfer::Write { lba, left: len as u32, off: 0, done: 0 },
                };
            }
            if let Xfer::Discard { left } = *xfer {
                let n = if left == 0 {
                    0
                } else {
                    let Ok(n) = cmd.read_data(&mut blk[..(left as usize).min(MAX_BLOCK)]) else {
                        *xfer = Xfer::None;
                        cmd.fail_phase();
                        return Ok(());
                    };
                    n as u32
                };
                if n >= left {
                    *xfer = Xfer::None;
                    cmd.fail(0);
                } else {
                    *xfer = Xfer::Discard { left: left - n };
                }
                return Ok(());
            }
            if let Xfer::Write { lba, left, off, done } = *xfer {
                let Ok(n) = cmd.read_data(&mut blk[off..bs as usize]) else {
                    *xfer = Xfer::None;
                    cmd.fail_phase();
                    return Ok(());
                };
                let off = off + n;
                let done = done + n as u32;
                if off >= bs as usize {
                    if !dev.write_block(lba, &blk[..bs as usize]) {
                        *sense = match dev.write_error() {
                            1 => SENSE_WRITE_PROTECTED,
                            2 => SENSE_BECOMING_READY,
                            _ => SENSE_WRITE_ERROR,
                        };
                        // The rest of the data phase is taken and dropped,
                        // then the command fails (as a refused WRITE: the
                        // CSW must follow the whole data phase).
                        let rest = (left - 1) * bs;
                        if rest == 0 {
                            *xfer = Xfer::None;
                            cmd.fail(0);
                        } else {
                            *xfer = Xfer::Discard { left: rest };
                        }
                        return Ok(());
                    }
                    if left <= 1 {
                        *xfer = Xfer::None;
                        cmd.pass(done);
                        return Ok(());
                    }
                    *xfer = Xfer::Write { lba: lba + 1, left: left - 1, off: 0, done };
                } else {
                    *xfer = Xfer::Write { lba, left, off, done };
                }
            }
        }
        // PREVENT ALLOW MEDIUM REMOVAL: accepted (a failed one makes Linux
        // stop sending them: sdev->lockable = 0), Prevent bit tracked per
        // LUN (LOCKED). An Allow on the generated volume lets a compaction
        // it was holding back run (vdisk.rs).
        ScsiCommand::Unknown { cmd: 0x1E } => {
            // Not exactly one CBW found: counts as Prevent (the safe side).
            let p = cdb4(core::borrow::BorrowMut::<[u8]>::borrow_mut(io), lun, 0x1E).map_or(true, |b| b & 1 != 0);
            if let Some(l) = LOCKED.get(lun as usize) {
                l.store(p, o);
            }
            #[cfg(feature = "vdisk")]
            if !p && dev.media_change_immediate() {
                crate::vdisk::on_unlock();
            }
            *sense = SENSE_OK;
            cmd.pass(0)
        }
        // START STOP UNIT. Any of them is noted for recovery.rs (it powers
        // off). LoEj = 1: eject (Start = 0) / load (Start = 1) the medium
        // (module text); LoEj = 0 (a plain stop / start), a power condition
        // (CB[4] bits 7..4) or a CBW not found exactly once: nothing else.
        ScsiCommand::Unknown { cmd: 0x1B } => {
            STOP_UNIT.store(true, o);
            let b4 = cdb4(core::borrow::BorrowMut::<[u8]>::borrow_mut(io), lun, 0x1B);
            SSU_COUNT.fetch_add(1, o);
            SSU_LAST.store(b4.map_or(0x100, u32::from), o);
            if let (Some(b), Some(e), Some(u)) = (b4, EJECTED.get(lun as usize), LOADED_UA.get(lun as usize)) {
                if b & 0xF2 == 0x02 {
                    let load = b & 1 != 0;
                    // A load of a medium that was ejected: the host has to
                    // re-read it (06/28/00); a load of a present one: nothing.
                    if load && e.load(o) {
                        u.store(true, o);
                    }
                    e.store(!load, o);
                }
            }
            *sense = SENSE_OK;
            cmd.pass(0)
        }
        _ => { *sense = SENSE_INVALID; cmd.fail(0); }
    }
    Ok(())
}

impl<B: UsbBus> UsbClass<B> for Msc<'_, B> {
    fn get_configuration_descriptors(&self, w: &mut DescriptorWriter) -> usb_device::Result<()> {
        self.scsi.get_configuration_descriptors(w)
    }
    fn reset(&mut self) {
        self.xfer = Xfer::None;
        // A packet of the interrupted data phase may still sit in the IN
        // endpoint (enabled, its FIFO flushed by the driver): drop it, or the
        // endpoint never sends again.
        crate::usb::abort_in(u8::from(self.scsi.in_address()));
        HOST_WRITING.store(false, core::sync::atomic::Ordering::Relaxed);
        // A bus reset starts a fresh session: a pending one-shot UNIT
        // ATTENTION from a screenshot taken while unplugged is moot (review
        // 2026-10-13 L3).
        crate::screenshot::MEDIUM_CHANGED.store(false, core::sync::atomic::Ordering::Relaxed);
        unlock_all();
        // A re-plug: an ejected medium is back.
        reload_all();
        // The generated volume: a new session may get a compacted layout.
        #[cfg(feature = "vdisk")]
        crate::vdisk::on_bus_reset();
        self.scsi.reset()
    }
    fn control_in(&mut self, xfer: ControlIn<B>) {
        self.scsi.control_in(xfer)
    }
    fn control_out(&mut self, xfer: ControlOut<B>) {
        // Bulk-Only Mass Storage Reset (the vendored usbd-storage resets
        // its transport on it): the command in progress is gone here too.
        let r = xfer.request();
        if r.request_type == usb_device::control::RequestType::Class
            && r.recipient == usb_device::control::Recipient::Interface
            && r.request == 0xFF
        {
            self.xfer = Xfer::None;
            // The packet of the data phase the host gave up (6.6.1: the
            // reset readies the device for the next CBW).
            crate::usb::abort_in(u8::from(self.scsi.in_address()));
        }
        self.scsi.control_out(xfer)
    }
    fn endpoint_out(&mut self, addr: EndpointAddress) {
        self.scsi.endpoint_out(addr)
    }
    fn endpoint_in_complete(&mut self, addr: EndpointAddress) {
        self.scsi.endpoint_in_complete(addr)
    }
    fn poll(&mut self) {
        self.scsi.poll()
    }
}

/// Set when the host sent SCSI START STOP UNIT (opcode 0x1B: eject, or a
/// stop / power-off request). usbd-storage hides the CDB bytes (LoEj/Start),
/// so any 0x1B counts; the native recovery mode powers off on it.
pub static STOP_UNIT: core::sync::atomic::AtomicBool = core::sync::atomic::AtomicBool::new(false);
